        ip->protocol != 17 || (size_t)ntohs(ip->total_length) + 14 != frame_len ||
        (ntohs(ip->flags_frag_off) != 0 && ntohs(ip->flags_frag_off) != 0x4000) ||
        epic_ipv4_checksum(ip, 20) != 0) return false;
    const epic_udp_t *udp = (const epic_udp_t *)(frame + 34);
    if (ntohs(udp->length) != ntohs(ip->total_length) - 20 ||
        ntohs(udp->src_port) != 4791 || ntohs(udp->dst_port) != 4791 ||
        udp->checksum != 0) return false;
    const epic_bth_t *bth = (const epic_bth_t *)(frame + 42);
    if (bth->se_m_pad != 0 || ntohs(bth->pkey) != 0xffff ||
        (ntohl(bth->qpn) >> 24) != 0) return false;
    uint32_t apsn = ntohl(bth->apsn), psn = apsn & 0xffffffu;
    if (bth->opcode == ROCE_OPCODE_ACK) {
        if (frame_len != 62 || (apsn >> 24) != 0) return false;
        uint32_t body;
        memcpy(&body, frame + 54, 4);
        body = ntohl(body);
        if (body != (0x1f000000u | ((psn + 1) & 0xffffffu))) return false;
        out->is_ack = true;
